export const DOC_GROUPS = ['Safe Work Method Statements', 'Policies', 'Contractor onboarding', 'Insurance', 'ABN registration'] as const
/** The order the groups show in: SWMS, Policies, Insurance, ABN, then Contractor onboarding. */
export const GROUP_ORDER = [0, 1, 3, 4, 2]

export const COMPLIANCE_DOCS: ComplianceDoc[] = [{"id": "SWMS 001","code": "SWMS 001","title": "Commercial Cleaning Operations","group": 0,"blocks": [{"k": "meta","items": ["Version 1.1","Issued 04/07/2026","Updated 11/11/2026 (added backpack vacuums)","Review by 04/07/2027","Approved by Laith Humadi, Director"]},{"k": "h","text": "Scope"},{"k": "p","text": "General commercial cleaning of offices, clinics, retail and shared spaces."},{"k": "h","text": "1. Wet or slippery floors during and after mopping"},{"k": "p","text": "Risk: Slips, trips and falls — sprains, fractures, bruising"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Place \"Wet Floor\" signs before starting","Mop in sections, leaving a dry walkway","Work in low-traffic periods where possible","Dry high-traffic areas promptly"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Slip-resistant footwear"]},{"k": "p","text": "Emergency: Assist anyone who falls, do not move them if injured; call 000 for serious injury and record the incident."},{"k": "h","text": "2. Cleaning chemicals (contact, splash, inhalation)"},{"k": "p","text": "Risk: Skin/eye irritation, respiratory irritation, burns"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Follow the Safety Data Sheet (SDS) for every product","Use correct dilution ratios — never mix products","Ensure ventilation when using strong chemicals","Keep chemicals labelled and lidded"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Chemical-resistant gloves","Safety glasses"]},{"k": "p","text": "Emergency: Flush skin/eyes with water for 15 minutes; refer to the SDS first-aid section; seek medical help if symptoms persist."},{"k": "h","text": "3. Manual handling of equipment, bins and stock"},{"k": "p","text": "Risk: Muscular strain, back injury"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Use correct lifting technique — bend knees, keep load close","Use trolleys for heavy or bulky loads","Team-lift anything over safe limits","Empty bins before they are overfull"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Gloves","Enclosed footwear"]},{"k": "p","text": "Emergency: Stop work, rest the injured area, apply first aid; report strains promptly so they can be managed early."},{"k": "h","text": "4. Electrical equipment and trailing cords (vacuums, machines)"},{"k": "p","text": "Risk: Electric shock, trips"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Visually check leads/plugs before use — tag out damaged gear","Keep cords clear of walkways and water","Use only tested-and-tagged equipment","Never operate electrical gear with wet hands"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Enclosed footwear"]},{"k": "p","text": "Emergency: Switch off power at the source before touching a shock victim; call 000; do not use damaged equipment."},{"k": "h","text": "5. Biological hazards — waste, washrooms, bodily fluids"},{"k": "p","text": "Risk: Infection, exposure to contaminants"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Treat all waste and washroom surfaces as potentially contaminated","Use dedicated colour-coded cloths/mops per area","Wash hands thoroughly after each task","Use a spill kit for bodily-fluid spills"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Disposable gloves","Face mask where required"]},{"k": "p","text": "Emergency: For a needle-stick or exposure, wash the area, do not scrub, and seek medical advice immediately; report it."},{"k": "h","text": "6. Working alone / after hours"},{"k": "p","text": "Risk: Delayed help if injured, personal security"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Keep a charged phone on you at all times","Advise a contact of start/finish times","Lock the site behind you; be aware of surroundings","Follow the site access and alarm procedure"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Hi-vis where required on site"]},{"k": "p","text": "Emergency: Call 000 in an emergency; then notify Core Cleaning on 0407 026 360."},{"k": "h","text": "7. Backpack vacuums (cords and surroundings)"},{"k": "p","text": "Risk: Electric shock, trips, knocking into people or objects, back strain"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Check the cord, plug and switch before every use; if wires are loose, exposed or damaged, tag it out and report it (never tape it)","Use an RCD; hook the cord on the harness and unplug by the plug, not the cord","Fit the harness and waist belt so the weight sits on your hips","The backpack makes you wider and taller: check behind before turning or stepping back, and take care in doorways and near fragile items","Look around often, as the noise hides people approaching; never use it on a ladder"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Enclosed footwear","Hearing protection where noisy"]},{"k": "p","text": "Emergency: Switch off at the power point before touching someone who has had a shock; call 000; report the incident."},{"k": "h","text": "Review"},{"k": "ul","items": ["Every 12 months","Following an incident","Following a significant change in work methods","Following introduction of new equipment or chemicals"]},{"k": "h","text": "Emergency contacts"},{"k": "ul","items": ["Emergency: 000","Poisons Information Centre: 13 11 26","Core Cleaning Management: 0407 026 360"]},{"k": "p","text": "This document has been prepared in accordance with the Work Health and Safety Act 2011 (Qld) and associated regulations."}]},{"id": "SWMS 002","code": "SWMS 002","title": "Chemical Handling & Storage","group": 0,"blocks": [{"k": "meta","items": ["Version 1.0","Issued 04/07/2026","Review by 04/07/2027","Approved by Laith Humadi, Director"]},{"k": "h","text": "Scope"},{"k": "p","text": "Handling, mixing, transporting and storing cleaning chemicals."},{"k": "h","text": "Chemicals covered"},{"k": "ul","items": ["Fast Glass","Shower Star","Kuranda Disinfectant","pH 7 Detergent","Sequal"]},{"k": "h","text": "1. Chemical splash to eyes or skin"},{"k": "p","text": "Risk: Eye injury, chemical burns, irritation"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Wear safety glasses and gloves when decanting or mixing","Follow the SDS for each product","Use correct dilution ratios; add chemical to water, not water to chemical","Pour at a low height to avoid splashing"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Chemical-resistant gloves","Safety glasses"]},{"k": "p","text": "Emergency: Flush the affected area with clean water for at least 15 minutes; follow SDS first aid; seek medical help."},{"k": "h","text": "2. Inhalation of fumes/vapours"},{"k": "p","text": "Risk: Respiratory irritation, dizziness, nausea"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Use in well-ventilated areas","Never mix bleach and acids/ammonia","Keep containers sealed when not in use","Use the minimum effective quantity"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Face mask / respirator where SDS requires"]},{"k": "p","text": "Emergency: Move to fresh air immediately; seek medical help if breathing difficulty continues."},{"k": "h","text": "3. Mixing incompatible chemicals"},{"k": "p","text": "Risk: Toxic gas, violent reaction"},{"k": "label","text": "Controls"},{"k": "ul","items": ["NEVER mix products","Use one product for one task","Rinse equipment between different chemicals","Keep original labels on all containers"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Gloves","Safety glasses"]},{"k": "p","text": "Emergency: Evacuate and ventilate the area; do not re-enter until clear; call 000 if anyone is affected."},{"k": "h","text": "4. Storage and spills"},{"k": "p","text": "Risk: Slips, contamination, reactions"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Store chemicals upright, lidded and labelled, away from food and heat","Keep an SDS folder accessible at each site","Keep a spill kit available","Store incompatible chemicals apart"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Gloves","Safety glasses"]},{"k": "p","text": "Emergency: Contain the spill with the spill kit, ventilate, and dispose of per the SDS; report the spill."},{"k": "h","text": "Review"},{"k": "ul","items": ["Every 12 months","Following an incident","Following a significant change in work methods","Following introduction of new equipment or chemicals"]},{"k": "h","text": "Emergency contacts"},{"k": "ul","items": ["Emergency: 000","Poisons Information Centre: 13 11 26","Core Cleaning Management: 0407 026 360"]},{"k": "p","text": "This document has been prepared in accordance with the Work Health and Safety Act 2011 (Qld) and associated regulations."}]},{"id": "SWMS 003","code": "SWMS 003","title": "Manual Handling","group": 0,"blocks": [{"k": "meta","items": ["Version 1.0","Issued 04/07/2026","Review by 04/07/2027","Approved by Laith Humadi, Director"]},{"k": "h","text": "Scope"},{"k": "p","text": "Lifting, carrying, pushing and pulling loads and equipment."},{"k": "h","text": "1. Lifting heavy or awkward loads"},{"k": "p","text": "Risk: Back and muscular strain"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Assess the load first; get help or a trolley if heavy","Bend the knees, keep the back straight, load close to the body","Avoid twisting — turn with the feet","Break loads into smaller amounts"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Gloves","Enclosed footwear"]},{"k": "p","text": "Emergency: Stop, rest and apply first aid; report any strain early so it can be managed."},{"k": "h","text": "2. Repetitive movements (scrubbing, wiping, vacuuming)"},{"k": "p","text": "Risk: Overuse injury, fatigue"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Alternate tasks and hands","Take short micro-breaks","Use ergonomic tools and extension handles","Keep equipment well maintained so it runs easily"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Gloves"]},{"k": "p","text": "Emergency: Rest the affected area; report persistent pain or numbness."},{"k": "h","text": "3. Pushing/pulling trolleys and machines"},{"k": "p","text": "Risk: Strain, collisions"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Push rather than pull where possible","Keep wheels/castors maintained","Keep clear sightlines; go slowly around corners","Do not overload trolleys"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Enclosed footwear"]},{"k": "p","text": "Emergency: Apply first aid to any strain or impact injury; report it."},{"k": "h","text": "Review"},{"k": "ul","items": ["Every 12 months","Following an incident","Following a significant change in work methods","Following introduction of new equipment or chemicals"]},{"k": "h","text": "Emergency contacts"},{"k": "ul","items": ["Emergency: 000","Poisons Information Centre: 13 11 26","Core Cleaning Management: 0407 026 360"]},{"k": "p","text": "This document has been prepared in accordance with the Work Health and Safety Act 2011 (Qld) and associated regulations."}]},{"id": "SWMS 004","code": "SWMS 004","title": "Slip, Trip & Fall Prevention","group": 0,"blocks": [{"k": "meta","items": ["Version 1.0","Issued 04/07/2026","Review by 04/07/2027","Approved by Laith Humadi, Director"]},{"k": "h","text": "Scope"},{"k": "p","text": "Preventing slips, trips and falls during all cleaning activities."},{"k": "h","text": "1. Wet floors"},{"k": "p","text": "Risk: Slips and falls"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Use \"Wet Floor\" signage","Clean in sections, leaving a dry path","Dry floors promptly in walkways","Wear slip-resistant footwear"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Slip-resistant footwear"]},{"k": "p","text": "Emergency: Assist anyone who falls; call 000 for serious injury; record the incident."},{"k": "h","text": "2. Trailing cords and hoses"},{"k": "p","text": "Risk: Trips"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Route cords along walls, away from walkways","Use the nearest power point","Coil unused cord","Warn others working nearby"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Enclosed footwear"]},{"k": "p","text": "Emergency: Apply first aid; report and photograph the hazard if it caused an injury."},{"k": "h","text": "3. Clutter, uneven surfaces, poor lighting"},{"k": "p","text": "Risk: Trips and falls"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Keep work areas tidy; clear obstacles before cleaning","Turn on lighting; report faulty lighting","Report damaged flooring to the client and Core Cleaning","Take extra care on stairs and ramps"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Enclosed footwear"]},{"k": "p","text": "Emergency: Apply first aid; report the hazard so it can be fixed."},{"k": "h","text": "4. Working at height (step stools, low ladders)"},{"k": "p","text": "Risk: Falls from height"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Use a rated, stable ladder/step on firm level ground","Maintain three points of contact; do not overreach","Do not stand on the top step","Have a second person foot the ladder where needed"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Slip-resistant footwear"]},{"k": "p","text": "Emergency: Do not move a seriously injured person; call 000; report the incident."},{"k": "h","text": "Review"},{"k": "ul","items": ["Every 12 months","Following an incident","Following a significant change in work methods","Following introduction of new equipment or chemicals"]},{"k": "h","text": "Emergency contacts"},{"k": "ul","items": ["Emergency: 000","Poisons Information Centre: 13 11 26","Core Cleaning Management: 0407 026 360"]},{"k": "p","text": "This document has been prepared in accordance with the Work Health and Safety Act 2011 (Qld) and associated regulations."}]},{"id": "SWMS 005","code": "SWMS 005","title": "Pressure Washing","group": 0,"blocks": [{"k": "meta","items": ["Version 1.0","Issued 04/07/2026","Review by 04/07/2027","Approved by Laith Humadi, Director"]},{"k": "h","text": "Scope"},{"k": "p","text": "High-pressure washing of hard surfaces, walkways, bins and exteriors."},{"k": "h","text": "1. High-pressure water jet"},{"k": "p","text": "Risk: Injection injury, lacerations to skin/eyes"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Never point the lance at people or yourself","Keep hands and feet clear of the nozzle","Start at low pressure and increase as needed","Release pressure before changing nozzles"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Safety glasses/face shield","Waterproof gloves","Enclosed waterproof footwear"]},{"k": "p","text": "Emergency: Treat any injection injury as serious — seek medical help immediately even if it looks minor."},{"k": "h","text": "2. Electricity near water"},{"k": "p","text": "Risk: Electric shock"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Use an RCD/safety switch on the supply","Keep leads and connections out of water","Inspect leads before use; tag out damaged gear","Never operate with wet hands on connections"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Waterproof footwear"]},{"k": "p","text": "Emergency: Isolate power before assisting a shock victim; call 000."},{"k": "h","text": "3. Flying debris and slippery surfaces"},{"k": "p","text": "Risk: Eye injury, slips"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Clear or cordon the area of people","Wear eye protection at all times","Be aware of the surface becoming slippery","Work away from your footing"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Safety glasses/face shield","Slip-resistant footwear"]},{"k": "p","text": "Emergency: Flush eyes with water; seek medical help for embedded debris."},{"k": "h","text": "4. Noise"},{"k": "p","text": "Risk: Hearing damage"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Wear hearing protection with petrol/high-noise units","Limit continuous exposure","Maintain the machine to reduce noise"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Hearing protection"]},{"k": "p","text": "Emergency: Report any ringing/loss of hearing; review controls."},{"k": "h","text": "Review"},{"k": "ul","items": ["Every 12 months","Following an incident","Following a significant change in work methods","Following introduction of new equipment or chemicals"]},{"k": "h","text": "Emergency contacts"},{"k": "ul","items": ["Emergency: 000","Poisons Information Centre: 13 11 26","Core Cleaning Management: 0407 026 360"]},{"k": "p","text": "This document has been prepared in accordance with the Work Health and Safety Act 2011 (Qld) and associated regulations."}]},{"id": "SWMS 006","code": "SWMS 006","title": "Floor Scrubbing & Polishing","group": 0,"blocks": [{"k": "meta","items": ["Version 1.0","Issued 04/07/2026","Review by 04/07/2027","Approved by Laith Humadi, Director"]},{"k": "h","text": "Scope"},{"k": "p","text": "Use of scrubbers, buffers and polishers on hard floors."},{"k": "h","text": "1. Rotating pad/brush entanglement"},{"k": "p","text": "Risk: Cuts, entanglement of clothing/cords"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Keep loose clothing, cords and hair clear","Never tilt/lift the machine while running","Switch off and unplug before changing pads","Keep bystanders clear"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Enclosed footwear"]},{"k": "p","text": "Emergency: Switch off immediately; apply first aid; report the incident."},{"k": "h","text": "2. Electrical (leads, wet operation)"},{"k": "p","text": "Risk: Electric shock"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Use an RCD/safety switch","Keep the lead behind the machine and out of water","Inspect leads; tag out damaged gear","Do not run cords through standing water"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Enclosed footwear"]},{"k": "p","text": "Emergency: Isolate power before assisting; call 000."},{"k": "h","text": "3. Wet/slippery floors and polish fumes"},{"k": "p","text": "Risk: Slips, respiratory irritation"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Signage and barriers around the work area","Ensure ventilation when applying polish/sealer","Follow SDS for stripper/sealer products","Allow floors to cure before re-opening"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Slip-resistant footwear","Gloves","Mask where SDS requires"]},{"k": "p","text": "Emergency: Move to fresh air for fume exposure; flush skin/eyes for chemical contact; seek help if needed."},{"k": "h","text": "4. Noise and vibration"},{"k": "p","text": "Risk: Hearing damage, fatigue"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Wear hearing protection where noisy","Take breaks; rotate operators","Maintain machines to reduce vibration"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Hearing protection"]},{"k": "p","text": "Emergency: Report hearing symptoms or hand numbness; review controls."},{"k": "h","text": "Review"},{"k": "ul","items": ["Every 12 months","Following an incident","Following a significant change in work methods","Following introduction of new equipment or chemicals"]},{"k": "h","text": "Emergency contacts"},{"k": "ul","items": ["Emergency: 000","Poisons Information Centre: 13 11 26","Core Cleaning Management: 0407 026 360"]},{"k": "p","text": "This document has been prepared in accordance with the Work Health and Safety Act 2011 (Qld) and associated regulations."}]},{"id": "SWMS 007","code": "SWMS 007","title": "Window Cleaning","group": 0,"blocks": [{"k": "meta","items": ["Version 1.1","Issued 04/07/2026","Updated 11/11/2026 (added razor blade scrapers)","Review by 04/07/2027","Approved by Laith Humadi, Director"]},{"k": "h","text": "Scope"},{"k": "p","text": "Internal and accessible external window and glass cleaning, including razor blade scrapers for stubborn deposits."},{"k": "h","text": "1. Working at height (ladders, low reach)"},{"k": "p","text": "Risk: Falls from height"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Use water-fed poles from the ground where possible","Use a rated, stable ladder on firm level ground","Maintain three points of contact; do not overreach","Do not work at height in high wind or wet conditions"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Slip-resistant footwear"]},{"k": "p","text": "Emergency: Do not move a seriously injured person; call 000; report the incident."},{"k": "h","text": "2. Glass breakage"},{"k": "p","text": "Risk: Lacerations"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Inspect glass for cracks before applying pressure","Use correct tools; do not force scrapers","Clean up broken glass with a dustpan, never bare hands","Report damaged glass to the client and Core Cleaning"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Cut-resistant gloves"]},{"k": "p","text": "Emergency: Apply pressure to bleeding cuts; seek medical help for deep wounds."},{"k": "h","text": "3. Cleaning chemicals and streaking solutions"},{"k": "p","text": "Risk: Skin/eye irritation"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Follow the SDS; use correct dilution","Avoid overhead spraying near the face","Ventilate internal areas"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Gloves","Safety glasses"]},{"k": "p","text": "Emergency: Flush skin/eyes with water; follow SDS first aid."},{"k": "h","text": "4. Weather and public access (external work)"},{"k": "p","text": "Risk: Slips, falls, struck-by"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Cordon the work area below","Postpone in rain/high wind","Watch for pedestrians and vehicles","Secure equipment against wind"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Hi-vis where required"]},{"k": "p","text": "Emergency: Apply first aid; call 000 for serious injury; report the incident."},{"k": "h","text": "5. Razor blade scrapers (calcium, paint, adhesive, construction residue)"},{"k": "p","text": "Risk: Cuts; scratched glass"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Only when washing won't remove it (hard water/calcium, paint, render, stickers, silicone)","Never on tinted, filmed, coated or plastic glass; test toughened glass in a corner first or ask Core Cleaning","Use a retractable holder with a new blade; keep the glass wet; push forward only at a low angle","Stop and report any scratch; retract the blade when not in use and dispose of used blades in a sharps container"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Cut-resistant gloves","Safety glasses"]},{"k": "p","text": "Emergency: Apply pressure to cuts; seek medical help for deep wounds; report the incident."},{"k": "h","text": "Review"},{"k": "ul","items": ["Every 12 months","Following an incident","Following a significant change in work methods","Following introduction of new equipment or chemicals"]},{"k": "h","text": "Emergency contacts"},{"k": "ul","items": ["Emergency: 000","Poisons Information Centre: 13 11 26","Core Cleaning Management: 0407 026 360"]},{"k": "p","text": "This document has been prepared in accordance with the Work Health and Safety Act 2011 (Qld) and associated regulations."}]},{"id": "SWMS 008","code": "SWMS 008","title": "Bond Cleaning Operations","group": 0,"blocks": [{"k": "meta","items": ["Version 1.0","Issued 04/07/2026","Review by 04/07/2027","Approved by Laith Humadi, Director"]},{"k": "h","text": "Scope"},{"k": "p","text": "End-of-lease bond cleans of vacant properties, including kitchens, bathrooms, ovens, carpets and fixtures, to inspection-ready standard."},{"k": "h","text": "Chemicals covered"},{"k": "ul","items": ["Oven degreaser","Mould & mildew remover","Kuranda Disinfectant","pH 7 Detergent"]},{"k": "h","text": "1. Oven and rangehood degreasing (confined space, strong chemicals)"},{"k": "p","text": "Risk: Skin/eye burns, respiratory irritation from concentrated degreaser"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Follow the SDS for the degreaser in use","Ventilate the kitchen — open windows/doors before starting","Apply in a well-lit area and avoid contact with skin","Never mix degreaser with other chemicals"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Chemical-resistant gloves","Safety glasses","Face mask"]},{"k": "p","text": "Emergency: Flush skin/eyes with water for 15 minutes; move to fresh air for fume exposure; seek medical help if symptoms persist."},{"k": "h","text": "2. Mould and mildew in bathrooms/wet areas"},{"k": "p","text": "Risk: Respiratory irritation, skin contact with mould spores and remover"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Ventilate the room before and during treatment","Follow the SDS dilution for mould/mildew remover","Avoid dry-brushing mould — dampen first to limit airborne spores","Do not mix mould remover with other chemicals"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Chemical-resistant gloves","Face mask","Safety glasses"]},{"k": "p","text": "Emergency: Move to fresh air if affected; flush skin/eyes with water; follow SDS first aid."},{"k": "h","text": "3. Unfamiliar / vacant property (no power, unknown layout, exposed hazards)"},{"k": "p","text": "Risk: Trips, falls, working in the dark, electrical hazards"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Confirm power/lighting is connected before starting; use a torch if not","Do a walkthrough first to identify hazards, damage or exposed wiring","Report any exposed wiring, gas smell or structural damage before working — do not proceed","Be alert for items left behind (sharps, broken glass)"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Enclosed footwear","Gloves"]},{"k": "p","text": "Emergency: Stop work and evacuate for a suspected gas leak or exposed live wiring; call 000/the relevant utility; notify Core Cleaning."},{"k": "h","text": "4. Older properties — pre-1990 renovations (potential asbestos-containing materials)"},{"k": "p","text": "Risk: Asbestos fibre exposure from damaged sheeting, tiles or textured surfaces"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Do not drill, sand, scrape or forcefully clean any damaged or friable wall/ceiling sheeting","If suspected asbestos-containing material is identified, stop work in that area and notify Core Cleaning and the property manager","Clean intact surfaces only with a damp cloth — never dry-sweep or use high pressure on suspect surfaces","Never attempt removal or disturbance of suspected ACM"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Gloves","Face mask where dust is present"]},{"k": "p","text": "Emergency: Stop work immediately, leave the area, and notify Core Cleaning management; do not disturb the material further."},{"k": "h","text": "5. Carpet steam cleaning (hot water, electrical equipment)"},{"k": "p","text": "Risk: Scalds, electric shock, slips on wet carpet"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Check leads and machine before use; use an RCD/safety switch","Keep the hot water hose and wand away from skin","Work from the back of the room to the exit to avoid re-walking wet carpet","Allow adequate drying time before the property is walked through"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Enclosed waterproof footwear","Gloves"]},{"k": "p","text": "Emergency: Isolate power before assisting a shock victim; run scalds under cool water; call 000 for serious injury."},{"k": "h","text": "6. Time pressure to meet agent/inspection deadlines"},{"k": "p","text": "Risk: Rushed work leading to slips, strains or missed hazards"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Plan the job realistically before booking; allow time for drying/curing","Do not skip PPE or SDS steps to save time","Ask for help or reschedule rather than rushing a hazardous task","Communicate delays to the client/agent early"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["As required per task above"]},{"k": "p","text": "Emergency: Stop and address any injury before continuing; report near-misses caused by time pressure."},{"k": "h","text": "Review"},{"k": "ul","items": ["Every 12 months","Following an incident","Following a significant change in work methods","Following introduction of new equipment or chemicals"]},{"k": "h","text": "Emergency contacts"},{"k": "ul","items": ["Emergency: 000","Poisons Information Centre: 13 11 26","Core Cleaning Management: 0407 026 360"]},{"k": "p","text": "This document has been prepared in accordance with the Work Health and Safety Act 2011 (Qld) and associated regulations."}]},{"id": "SWMS 009","code": "SWMS 009","title": "Residential Cleaning Operations","group": 0,"blocks": [{"k": "meta","items": ["Version 1.1","Issued 04/07/2026","Updated 11/11/2026 (added backpack vacuums)","Review by 04/07/2027","Approved by Laith Humadi, Director"]},{"k": "h","text": "Scope"},{"k": "p","text": "Routine and deep cleaning of occupied private homes, including kitchens, bathrooms, living areas and bedrooms, while residents, children or pets may be present."},{"k": "h","text": "1. Occupied home — residents, children and visitors present"},{"k": "p","text": "Risk: Slips/collisions in shared spaces, privacy concerns, disruption to the household"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Confirm the cleaning schedule and any areas to avoid with the client beforehand","Keep work areas tidy and clear as you go to avoid trip hazards for residents","Respect private/off-limits rooms and personal belongings","Pause chemical use in a room if a child is present until it is ventilated"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Enclosed footwear"]},{"k": "p","text": "Emergency: If a resident is injured due to the clean, apply first aid where appropriate and notify Core Cleaning immediately."},{"k": "h","text": "2. Pets in the home"},{"k": "p","text": "Risk: Bites, scratches, tripping over animals, chemical exposure to pets"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Ask the client to secure pets before the clean where possible","Keep chemicals, mop buckets and cords out of reach of pets","Move calmly around animals; do not corner or startle them","Close doors/gates behind you to keep pets out of wet or chemical-treated areas"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Gloves"]},{"k": "p","text": "Emergency: For a bite or scratch, wash the wound thoroughly and seek medical advice if it breaks the skin; report the incident."},{"k": "h","text": "3. Unknown household hazards (clutter, stairs, uneven surfaces, pests)"},{"k": "p","text": "Risk: Slips, trips and falls"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Do a quick visual check of each room before starting","Ask the client to clear valuable/fragile clutter from work areas beforehand","Take extra care on stairs and with loose rugs/cords","Report any pest activity or hazardous conditions to Core Cleaning"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Enclosed, slip-resistant footwear"]},{"k": "p","text": "Emergency: Assist anyone who falls; call 000 for serious injury; record and report the incident."},{"k": "h","text": "4. Kitchen and bathroom chemical use in a lived-in home"},{"k": "p","text": "Risk: Skin/eye irritation, accidental exposure to residents or pets"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Follow the SDS for every product used","Never leave chemicals unattended or within reach of children/pets","Ventilate the room during and after use","Store and transport chemicals securely between homes"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Chemical-resistant gloves","Safety glasses"]},{"k": "p","text": "Emergency: Flush skin/eyes with water for 15 minutes; follow SDS first aid; seek medical help if symptoms persist."},{"k": "h","text": "5. Working alone in a private residence"},{"k": "p","text": "Risk: Delayed help if injured, personal security"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Keep a charged phone on you at all times","Advise Core Cleaning or a contact of the address and expected finish time","Trust your judgement — leave and report if a situation feels unsafe","Confirm identity/access with the client or agent before entering"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["As required per task"]},{"k": "p","text": "Emergency: Call 000 in an emergency; then notify Core Cleaning on 0407 026 360."},{"k": "h","text": "6. Backpack vacuums (cords and surroundings)"},{"k": "p","text": "Risk: Electric shock, trips, knocking into people or objects, back strain"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Check the cord, plug and switch before every use; if wires are loose, exposed or damaged, tag it out and report it (never tape it)","Use an RCD; hook the cord on the harness and unplug by the plug, not the cord","Fit the harness and waist belt so the weight sits on your hips","The backpack makes you wider and taller: check behind before turning or stepping back, and take care in doorways and near fragile items","Look around often, as the noise hides people approaching; never use it on a ladder"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Enclosed footwear","Hearing protection where noisy"]},{"k": "p","text": "Emergency: Switch off at the power point before touching someone who has had a shock; call 000; report the incident."},{"k": "h","text": "Review"},{"k": "ul","items": ["Every 12 months","Following an incident","Following a significant change in work methods","Following introduction of new equipment or chemicals"]},{"k": "h","text": "Emergency contacts"},{"k": "ul","items": ["Emergency: 000","Poisons Information Centre: 13 11 26","Core Cleaning Management: 0407 026 360"]},{"k": "p","text": "This document has been prepared in accordance with the Work Health and Safety Act 2011 (Qld) and associated regulations."}]},{"id": "SWMS 010","code": "SWMS 010","title": "Vinyl Floor Strip and Seal","group": 0,"blocks": [{"k": "meta","items": ["Version 1.0","Issued 11/11/2026","Review by 11/11/2027","Approved by Laith Humadi, Director"]},{"k": "h","text": "Scope"},{"k": "p","text": "Stripping and resealing vinyl and other resilient floors with chemical stripper and a rotary machine."},{"k": "h","text": "1. Floor stripper (strong alkaline chemical)"},{"k": "p","text": "Risk: Chemical burns, eye damage, fume irritation"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Follow the SDS and label dilution; never mix with other products","Add chemical to water, in a ventilated area","Test on a small hidden area first to check the floor type","Keep clean water or an eye wash bottle nearby"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Chemical-resistant gloves","Splash goggles","Waterproof boots"]},{"k": "p","text": "Emergency: Flush skin/eyes with water for 15 minutes; call 13 11 26 or 000 if serious."},{"k": "h","text": "2. Extremely slippery stripper slurry"},{"k": "p","text": "Risk: Slips and falls"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Close the area with signs and barriers at every entry","Work in small sections towards the exit; keep a dry path out","Pick up slurry promptly with a wet vac","Never tip slurry into stormwater drains or gardens"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Slip-resistant footwear or strip overshoes"]},{"k": "p","text": "Emergency: Do not move a seriously injured person; call 000; report the incident."},{"k": "h","text": "3. Rotary machine and electrics in the wet"},{"k": "p","text": "Risk: Loss of control, electric shock"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Trained operators only; check the pad is secure before starting","Use an RCD/safety switch and tested-and-tagged leads","Keep plugs and leads out of slurry and water","Switch off and unplug before changing pads"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Enclosed slip-resistant footwear","Hearing protection where noisy"]},{"k": "p","text": "Emergency: Isolate power before helping anyone; call 000."},{"k": "h","text": "4. Sealer and floor finish"},{"k": "p","text": "Risk: Fume irritation, slips on wet finish"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Ventilate during application and drying","No ignition sources near solvent-based products","Apply thin coats and allow full drying time","Keep the area closed until dry"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Gloves","Mask where the SDS requires"]},{"k": "p","text": "Emergency: Move to fresh air; follow SDS first aid."},{"k": "h","text": "Review"},{"k": "ul","items": ["Every 12 months","Following an incident","Following a significant change in work methods","Following introduction of new equipment or chemicals"]},{"k": "h","text": "Emergency contacts"},{"k": "ul","items": ["Emergency: 000","Poisons Information Centre: 13 11 26","Core Cleaning Management: 0407 026 360"]},{"k": "p","text": "This document has been prepared in accordance with the Work Health and Safety Act 2011 (Qld) and associated regulations."}]},{"id": "SWMS 011","code": "SWMS 011","title": "Carpet Steam Cleaning","group": 0,"blocks": [{"k": "meta","items": ["Version 1.0","Issued 11/11/2026","Review by 11/11/2027","Approved by Laith Humadi, Director"]},{"k": "h","text": "Scope"},{"k": "p","text": "Hot water extraction (steam) cleaning of carpets and rugs with a portable machine."},{"k": "h","text": "1. Hot water, hoses and electrics"},{"k": "p","text": "Risk: Scalds, electric shock"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Check hoses, wand, leads and plug before use; tag out damaged gear","Use an RCD/safety switch; keep leads off wet carpet","Connect hoses only with the machine off; never point the wand at people or pets"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Gloves","Enclosed footwear"]},{"k": "p","text": "Emergency: Cool burns under running water for 20 minutes; isolate power before helping anyone; call 000 if serious."},{"k": "h","text": "2. Pre-sprays, spotters and soiling (pet urine, vomit)"},{"k": "p","text": "Risk: Skin/eye irritation, fumes, infection"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Follow the SDS and dilution; ventilate the room","Use wool-safe products and test colourfastness on a hidden spot","Remove solids with gloves first; do not handle needles or sharps"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Gloves","Safety glasses","Mask where the SDS requires"]},{"k": "p","text": "Emergency: Flush skin/eyes with water; call 13 11 26; report any exposure."},{"k": "h","text": "3. Wet carpet, hoses and leads"},{"k": "p","text": "Risk: Slips and trips"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Run hoses and leads along walls, away from walkways","Work towards the door so you never cross wet carpet","Warn occupants which rooms are wet and how long to keep off"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Slip-resistant footwear"]},{"k": "p","text": "Emergency: Do not move a seriously injured person; call 000; report the incident."},{"k": "h","text": "4. Machine on stairs and moving furniture"},{"k": "p","text": "Risk: Strains, crush injuries, carpet damage"},{"k": "label","text": "Controls"},{"k": "ul","items": ["Two-person lift on stairs; ask the client to move heavy items first","Put tabs or foil under furniture legs on damp carpet","Don't over-wet; empty dirty water into the sewer, never stormwater"]},{"k": "label","text": "PPE"},{"k": "ul","items": ["Gloves"]},{"k": "p","text": "Emergency: Stop and report any strain; apply first aid."},{"k": "h","text": "Review"},{"k": "ul","items": ["Every 12 months","Following an incident","Following a significant change in work methods","Following introduction of new equipment or chemicals"]},{"k": "h","text": "Emergency contacts"},{"k": "ul","items": ["Emergency: 000","Poisons Information Centre: 13 11 26","Core Cleaning Management: 0407 026 360"]},{"k": "p","text": "This document has been prepared in accordance with the Work Health and Safety Act 2011 (Qld) and associated regulations."}]},{"id": "POL-002","code": "POL-002","title": "Environmental Policy","group": 1,"blocks": [{"k": "meta","items": ["Version 1.0","Issued 04/07/2026","Review by 04/07/2027","Approved by Laith Humadi, Director"]},{"k": "p","text": "Core Cleaning is committed to minimising the environmental impact of its operations and to continual improvement in its environmental performance."},{"k": "h","text": "Waste reduction"},{"k": "p","text": "We minimise waste by using the correct amount of product, reusing durable equipment, and disposing of waste responsibly and in line with site requirements."},{"k": "h","text": "Responsible chemical use"},{"k": "p","text": "Chemicals are used strictly in accordance with their Safety Data Sheets and at the correct dilution. We avoid over-use and select lower-toxicity, environmentally responsible products where practical."},{"k": "h","text": "Recycling"},{"k": "p","text": "We separate and recycle materials where site facilities allow, and encourage clients to support recycling on their premises."},{"k": "h","text": "Water & energy conservation"},{"k": "p","text": "We use water efficiently, avoid unnecessary running of taps and equipment, and switch off lights and equipment that are not in use."},{"k": "h","text": "Compliance"},{"k": "p","text": "Core Cleaning complies with all applicable environmental laws and regulations, and reviews this policy at least annually."}]},{"id": "POL-003","code": "POL-003","title": "Business Continuity Plan","group": 1,"blocks": [{"k": "meta","items": ["Version 1.0","Issued 04/07/2026","Review by 04/07/2027","Approved by Laith Humadi, Director"]},{"k": "p","text": "This plan sets out how Core Cleaning maintains service to clients during a disruption. It is reviewed annually and after any activation."},{"k": "h","text": "Cleaner unavailable or resigns"},{"k": "ul","items": ["A backup cleaner or subcontractor from our bench is deployed","Site Packs (site details, access, scope) let a replacement step in and perform correctly","The client is notified if any change to timing is expected"]},{"k": "h","text": "Flood, fire or site incident"},{"k": "ul","items": ["The client and management are notified immediately","Affected cleans are rescheduled once the site is safe","Alternative arrangements are made where access is lost"]},{"k": "h","text": "Vehicle breakdown"},{"k": "ul","items": ["Backup or hired transport is arranged","Affected sites are re-sequenced or rescheduled the same day where possible"]},{"k": "h","text": "Equipment failure"},{"k": "ul","items": ["Spare or hired equipment is sourced","Supplier contacts are maintained for rapid replacement"]},{"k": "h","text": "Pandemic or widespread illness"},{"k": "ul","items": ["Enhanced hygiene protocols are followed","Essential/priority sites are maintained first","Coordination continues remotely via Core Cleaning Hub"]},{"k": "h","text": "Key person unavailable"},{"k": "ul","items": ["Operations are documented in Core Cleaning Hub so the business runs without a single point of failure","A delegated contact manages client communication"]},{"k": "h","text": "Communication"},{"k": "p","text": "Clients are kept informed promptly during any disruption. Core Cleaning management can be reached on 0407 026 360."}]},{"id": "MS","code": "POLICY","title": "Modern Slavery Declaration","group": 1,"blocks": [{"k": "meta","items": ["Version 1.0","Issued 04/07/2026","Review by 04/07/2027","Approved by Laith Humadi, Director"]},{"k": "p","text": "Core Cleaning is committed to ethical business practices and does not tolerate any form of modern slavery, forced labour, child labour, human trafficking, or exploitation within its operations or supply chain."},{"k": "p","text": "Core Cleaning requires all subcontractors and suppliers to comply with applicable workplace, employment, and human rights laws."},{"k": "p","text": "Core Cleaning verifies contractor identity, ABN registration, and right-to-work status where applicable."},{"k": "p","text": "Any suspected breach of this policy must be reported immediately to Core Cleaning management."}]},{"id": "SDS","code": "SDS-REG","title": "Safety Data Sheet (SDS) Register","group": 1,"blocks": [{"k": "meta","items": ["Version 1.0","Issued 04/07/2026","Review by 04/07/2027","Approved by Laith Humadi, Director"]},{"k": "p","text": "Current Safety Data Sheets for all chemicals in use are available to workers. Each SDS must be read before first use of a product and followed at all times."},{"k": "h","text": "Products"},{"k": "ul","items": ["Agar Fast Glass: SDS Aug 2023. Warning: eye irritant. PPE: eye protection.","Agar Shower Star: SDS Oct 2024. Danger: serious eye damage, skin irritant. PPE: goggles, gloves.","Agar Kuranda Disinfectant: SDS Sep 2024. Warning: skin and eye irritant. PPE: glasses, gloves.","Agar pH-7 Neutral Detergent: SDS Mar 2024. Danger: serious eye damage, skin irritant. PPE: goggles, gloves.","Agar Sequal: SDS Sep 2025. Danger: serious eye damage. PPE: goggles, gloves.","Peerless JAL One Shot Thick: SDS Jul 2023. Warning: skin and eye irritant. PPE: safety glasses, nitrile gloves.","Sampson Shower Shine: SDS Jan 2026. Danger: serious eye damage, skin irritant. PPE: goggles, gloves.","Easy-Off Oven Heavy Duty (325 g aerosol): SDS May 2020. Danger: flammable aerosol, corrosive. PPE: goggles, chemical gloves, good ventilation.","Pine O Cleen Disinfectant Liquid Eucalyptus: SDS Dec 2025. Warning: skin and eye irritant. PPE: gloves.","Bissell Wash & Protect Stain & Odour: SDS Feb 2023. Warning: eye irritant. PPE: nitrile gloves.","Britex Deep Cleaning Carpet Cleaner: SDS Dec 2020. Danger: serious eye damage, skin irritant, harmful to aquatic life. PPE: chemical goggles, PVC gloves.","Selleys Rapid Mould Killer (contains bleach): SDS Mar 2018. Danger: serious eye damage, skin irritant. PPE: chemical goggles, nitrile gloves."]},{"k": "h","text": "Never mix"},{"k": "p","text": "Acid products (Sequal, One Shot Thick, Shower Star, Shower Shine) must never be mixed or used together with bleach, including Selleys Rapid Mould Killer, or with the alkaline Easy-Off oven cleaner. Acid and bleach together release chlorine gas. Never spray Rapid Mould Killer in a shower or toilet that has just been cleaned with an acid product: rinse well first."}]},{"id": "DCA-SUB","code": "DCA-SUB","title": "Subcontractor Services Agreement","group": 2,"blocks": [{"k": "p","text": "This Agreement sets out the terms on which the Subcontractor provides cleaning services to Core Cleaning as an independent contractor. By signing, the Subcontractor agrees to be bound by these terms."},{"k": "h","text": "1. Engagement & Independent Contractor Status"},{"k": "p","text": "Core Cleaning engages the Subcontractor to perform cleaning services at sites allocated from time to time. The Subcontractor is an independent contractor, not an employee, partner or agent of Core Cleaning. The Subcontractor is responsible for their own tax, superannuation, insurances and business costs, and is free to accept or decline allocated work."},{"k": "h","text": "2. Services & Standards"},{"k": "p","text": "The Subcontractor will perform the services to a professional commercial standard, in accordance with the site scope, Core Cleaning’s procedures and any reasonable direction as to the result required. The Subcontractor provides their own skill, method and supervision. Deficiencies notified within a reasonable time will be rectified at the Subcontractor’s cost."},{"k": "h","text": "3. Fees, Invoicing & Payment"},{"k": "p","text": "Core Cleaning will pay the agreed fee for completed services. The Subcontractor invoices Core Cleaning (with a valid ABN and, where registered, GST) per the agreed cycle. Payment is made within the agreed payment period to the Subcontractor’s nominated account. The Subcontractor is not entitled to leave, allowances or employment entitlements."},{"k": "h","text": "4. Insurance"},{"k": "p","text": "The Subcontractor must hold and maintain current Public Liability insurance of not less than $10 million, and Workers’ Compensation insurance where they engage workers, for the term of this Agreement. Certificates of Currency must be provided to Core Cleaning on request and kept current. Work must not be performed while cover has lapsed."},{"k": "h","text": "5. Work Health & Safety"},{"k": "p","text": "The Subcontractor will comply with the Work Health and Safety Act 2011 (Qld) and related regulations, Core Cleaning’s Safe Work Method Statements (SWMS) and Safety Data Sheets (SDS), and all site safety rules. The Subcontractor is responsible for the safety of their own personnel and for reporting incidents and hazards promptly."},{"k": "h","text": "6. Confidentiality & Non-Solicitation"},{"k": "p","text": "The Subcontractor will keep confidential all client, site and business information and access credentials, and use them only to perform the services. During the term and for six months after, the Subcontractor will not directly solicit or service Core Cleaning’s clients introduced through this engagement without Core Cleaning’s written consent."},{"k": "h","text": "7. Equipment, Materials & Chemicals"},{"k": "p","text": "Unless otherwise agreed, the Subcontractor supplies their own equipment and materials, maintained in safe working order (electrical items tested and tagged). Chemicals must be used strictly per the SDS and correct dilution. The Subcontractor must not mix products or use unapproved chemicals on site."},{"k": "h","text": "8. Conduct, Uniform & Presentation"},{"k": "p","text": "The Subcontractor and their personnel will present neatly and professionally, wear the required uniform/ID where applicable, conduct themselves courteously on site, and respect client property and privacy. Behaviour that damages Core Cleaning’s reputation or a client relationship is a breach of this Agreement."},{"k": "h","text": "9. Incident & Hazard Reporting"},{"k": "p","text": "The Subcontractor will report any incident, injury, near-miss, damage or hazard to Core Cleaning management without delay, and cooperate with any investigation. Serious incidents must be reported immediately by phone."},{"k": "h","text": "10. Subcontractor’s Personnel"},{"k": "p","text": "The Subcontractor is responsible for the recruitment, vetting, right-to-work checks, training, induction, supervision and payment of their own personnel, and ensures each has read and understood the relevant induction and SWMS before commencing work."},{"k": "h","text": "11. Compliance with Laws & Modern Slavery"},{"k": "p","text": "The Subcontractor will comply with all applicable workplace, employment, tax and human-rights laws, and with Core Cleaning’s Modern Slavery position: no forced labour, child labour, human trafficking or exploitation in its operations or supply chain. Any suspected breach must be reported immediately."},{"k": "h","text": "12. Liability & Indemnity"},{"k": "p","text": "The Subcontractor indemnifies Core Cleaning against loss or claims arising from the Subcontractor’s negligence, breach of this Agreement, or the acts of its personnel. Each party is responsible for its own insurable risks. Nothing limits rights that cannot be excluded under the Australian Consumer Law."},{"k": "h","text": "13. Term, Suspension & Termination"},{"k": "p","text": "This Agreement applies from the date signed and continues until terminated. Either party may terminate on reasonable written notice. Core Cleaning may suspend or terminate immediately for a material breach, a lapse of insurance, a serious safety breach, or conduct that harms a client relationship. On termination the Subcontractor returns all keys, fobs, access devices and confidential material."},{"k": "h","text": "14. GST, ABN & General"},{"k": "p","text": "The Subcontractor warrants its ABN and, where applicable, GST registration. This Agreement is governed by the laws of Queensland. It is the entire agreement between the parties; any variation must be in writing. A failure to enforce a term is not a waiver. If a provision is unenforceable it is severed and the remainder continues. This Agreement may be signed electronically."}]},{"id": "IND-001","code": "IND-001","title": "Contractor Induction","group": 2,"blocks": [{"k": "p","text": "Welcome to Core Cleaning. This induction sets out how we work and what we expect on every site. Please read it in full before commencing. It applies to you and to any of your personnel."},{"k": "h","text": "Business rules"},{"k": "ul","items": ["Perform every clean to the agreed site scope and a professional commercial standard","Follow reasonable directions about the result required","Respect client property, privacy and premises at all times"]},{"k": "h","text": "Uniform & presentation"},{"k": "ul","items": ["Wear clean, neat, appropriate clothing and closed footwear","Wear the required uniform / ID where applicable","Maintain a tidy, professional appearance on every site"]},{"k": "h","text": "Conduct expectations"},{"k": "ul","items": ["Be courteous and professional with clients and the public","No smoking, alcohol or drugs on site","Do not use client facilities, phones or equipment without permission"]},{"k": "h","text": "Site security & access"},{"k": "ul","items": ["Follow each site’s access, key/fob and alarm procedure exactly","Never share access codes or keys","Lock up and re-set alarms when leaving; leave the site secure"]},{"k": "h","text": "Client confidentiality"},{"k": "ul","items": ["Keep all client and site information confidential","Do not photograph or share client premises except for approved job photos","Secure and do not disturb client documents, cash or valuables"]},{"k": "h","text": "Safety & SWMS"},{"k": "ul","items": ["Read and follow the relevant Safe Work Method Statement for your work","Assess each site for hazards before starting","Use \"Wet Floor\" signage; keep walkways and cords clear"]},{"k": "h","text": "Chemical handling & SDS"},{"k": "ul","items": ["Read the Safety Data Sheet before first use of any product","Use correct dilution ratios; never mix products","Keep chemicals labelled, lidded and stored safely"]},{"k": "h","text": "PPE requirements"},{"k": "ul","items": ["Wear the PPE specified in the SWMS/SDS (gloves, safety glasses, etc.)","Inspect PPE before use; replace damaged items","Use hearing protection with high-noise equipment"]},{"k": "h","text": "Incident & hazard reporting"},{"k": "ul","items": ["Report any incident, injury, near-miss, damage or hazard to Core Cleaning management without delay","Report serious incidents immediately by phone","Cooperate with any investigation"]},{"k": "h","text": "Emergency procedures"},{"k": "ul","items": ["Emergency: 000 · Poisons Information Centre: 13 11 26","Core Cleaning Management: 0407 026 360","Know the site’s exits and evacuation points"]},{"k": "h","text": "Invoicing process"},{"k": "ul","items": ["Invoice Core Cleaning per the agreed cycle with a valid ABN","Include GST only if registered","Payment is made to your nominated account within the agreed terms"]},{"k": "h","text": "Communication standards"},{"k": "ul","items": ["Respond to Core Cleaning communications promptly","Advise as early as possible if you cannot attend a clean","Raise any issues on site with Core Cleaning management, not the client"]},{"k": "h","text": "Attendance & reliability"},{"k": "ul","items": ["Attend allocated cleans on the scheduled day/time","Arrange a suitable replacement from your team if you are unavailable","Consistent no-shows are a breach of your agreement"]},{"k": "h","text": "Acknowledgment"},{"k": "p","text": "I confirm I have read and understood this induction."}]},{"id": "COC","code": "COC","title": "Certificate of Currency (Public Liability)","group": 3,"pdf": "/documents/compliance/certificate-of-currency.pdf","pdfName": "OA94565187 Certificate of Currency.pdf","blocks": [{"k": "meta","items": ["Youi policy OA94565187","Issued 24/08/2026","Cover 14/07/2026 to 13/07/2027"]},{"k": "h","text": "Cover"},{"k": "ul","items": ["Public and Product Liability: $10,000,000","Advertising Liability: $1,000,000 (sub-limit)","Goods In Care: $250,000 (sub-limit)"]},{"k": "h","text": "Insured"},{"k": "p","text": "Laith Humadi (trading as Core Cleaning), ABN 45 344 135 153."},{"k": "h","text": "Special conditions"},{"k": "ul","items": ["No cover for cleaning services for hospitals or aged care facilities.","No cover for external building cleaning above 10 metres or 3 storeys, whichever is lower.","An additional $10,000 excess applies to claims for injury to a subcontractor or damage to a subcontractor's property."]},{"k": "p","text": "The certificate is attached as a PDF. Open it to view or download the original."}]},{"id": "ABN","code": "ABN","title": "ABN Registration (ABN Lookup printout)","group": 4,"pdf": "/documents/compliance/abn-printout.pdf","pdfName": "ABN Printout Core Cleaning.pdf","blocks": [{"k": "meta","items": ["ABN 45 344 135 153","Record extracted 13/08/2026"]},{"k": "h","text": "ABN details"},{"k": "ul","items": ["Entity name: Humadi, Laith","ABN status: Active from 28 Jun 2026","Entity type: Individual/Sole Trader","GST: Registered from 03 Aug 2026","Main business location: QLD 4031"]},{"k": "p","text": "The ABN Lookup printout is attached as a PDF. Open it to view or download the original."}]}]

export const docById = (id: string) => COMPLIANCE_DOCS.find(d => d.id === id)
/** Ids in a URL: "SWMS 001" → "swms-001" */
export const docSlug = (id: string) => id.toLowerCase().replace(/\s+/g, '-')
export const docBySlug = (slug: string) => COMPLIANCE_DOCS.find(d => docSlug(d.id) === String(slug || '').toLowerCase())
export function docFileName(d: ComplianceDoc): string {
  if (d.pdfName) return d.pdfName
  return ((d.code ? d.code + ' ' : '') + (d.title || 'Document')).replace(/[\\/:*?"<>|]+/g, '-').replace(/\s+/g, ' ').trim() + '.pdf'
}
const ids = (fn: (d: ComplianceDoc) => boolean) => COMPLIANCE_DOCS.filter(fn).map(d => d.id)
/** The built-in quick sets (mock-up setDefs). */
export const QUICK_SETS: { name: string; ids: string[] }[] = [
  { name: 'Client pack', ids: ids(d => d.group !== 2) },
  { name: 'Subcontractor pack', ids: ids(d => d.group === 0 || d.group === 2) },
  { name: 'Chemical safety', ids: ['SWMS 002', 'SDS'] },
]

/** The old public links (/compliance/<slug>) still in use, mapped to the library. */
const OLD_SLUGS: Record<string, string> = { 'environmental-policy': 'POL-002', 'business-continuity': 'POL-003', 'modern-slavery': 'MS', 'sds-register': 'SDS' }
/** A document anyone may open at /compliance/<slug>: everything but the subcontractor agreement and induction. */
export function publicDoc(slug: string): ComplianceDoc | undefined {
  const s = String(slug || '').toLowerCase()
  const d = OLD_SLUGS[s] ? docById(OLD_SLUGS[s]) : docBySlug(s)
  return d && d.group !== 2 ? d : undefined
}
